/* Internal notify service: the single outbound exit for every push
   (briefs / alerts / reminders / delegated todos). Auth: same Bearer key.
   B2: an optional `owner` routes the message to that person's channel.
   When they have no usable channel (or are unknown/inactive) we fall back
   to the machine owner and flag `degraded` — never silently dropped. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(/^Bearer\s+/i, '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
const body = req.body || {};
const message = String(body.message || '').trim();
if (!message) {
  return [{ json: { __error: true, status: 400, body: { error: { message: 'message is required', type: 'invalid_request_error' } } } }];
}
const kind = String(body.kind || '通知').slice(0, 40);
const owner = String(body.owner || '').trim().replace(/^@/, '');

/* ---- B2: resolve the person's channel (only when an owner was requested) ---- */
let degraded = false;
let resolved_to = '';
let chan = null;
if (owner) {
  try {
    const api = (u) => this.helpers.httpRequest({ method: 'GET', url: u, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY }, timeout: 10000 });
    const list = await api('http://localhost:5678/api/v1/data-tables?limit=100');
    const pid = ((list.data || []).find((t) => t.name === 'people') || {}).id;
    if (pid) {
      const rows = await api('http://localhost:5678/api/v1/data-tables/' + pid + '/rows?limit=200');
      const p = ((rows.data || []).find((x) => x.name === owner)) || null;
      if (p && (p.active === 1 || p.active === true)) {
        let c = {};
        try { c = JSON.parse(p.channels || '{}'); } catch (e) { c = {}; }
        chan = { tg: String(c.telegram_chat_id || '').trim(), hook: String(c.webhook_url || '').trim() };
        resolved_to = owner;
      }
    }
  } catch (e) { /* lookup failed -> fall back to the default target */ }
  if (!resolved_to || !chan || (!chan.tg && !chan.hook)) degraded = true;
}

let fmt = String($env.ALERT_WEBHOOK_FORMAT || '').toLowerCase().trim();
if (fmt === 'auto') fmt = '';
let text = '[PivotAI] ' + kind + ' · ' + message;
if (owner && degraded) text += String.fromCharCode(10) + '（注：' + owner + ' 没有可用通道，已改投机主）';
let url = '';
let payload;
let via = 'default';
if (chan && chan.tg) {
  const tgToken = String($env.TELEGRAM_BOT_TOKEN || '').trim();
  if (tgToken) {
    url = 'https://api.telegram.org/bot' + tgToken + '/sendMessage';
    payload = { chat_id: chan.tg, text: text.slice(0, 4000), disable_web_page_preview: true };
    via = 'person:telegram';
  }
}
if (via === 'default' && chan && chan.hook) {
  url = chan.hook;
  payload = { source: 'agent-platform', kind, text, owner, at: new Date().toISOString() };
  via = 'person:webhook';
}
if (via === 'default') {
  if (fmt === 'telegram') {
    const tgToken = String($env.TELEGRAM_BOT_TOKEN || '').trim();
    const tgChat = String($env.TELEGRAM_CHAT_ID || '').trim();
    if (!tgToken || !tgChat) {
      return [{ json: { __error: true, status: 200, body: { ok: false, reason: 'skipped:no-channel', detail: 'telegram not fully configured', kind, owner, degraded } } }];
    }
    url = 'https://api.telegram.org/bot' + tgToken + '/sendMessage';
    payload = { chat_id: tgChat, text: text.slice(0, 4000), disable_web_page_preview: true };
  } else {
    url = String($env.ALERT_WEBHOOK_URL || '').trim();
    if (!url) {
      // No channel configured: respond 200 with a structured skip (graceful).
      return [{ json: { __error: true, status: 200, body: { ok: false, reason: 'skipped:no-channel', kind, owner, degraded } } }];
    }
    if (!fmt || fmt === 'generic') {
      if (/feishu|open\.feishu\.cn|larksuite/i.test(url)) fmt = 'feishu';
      else if (/qyapi\.weixin\.qq\.com/i.test(url)) fmt = 'wecom';
      else if (/hooks\.slack\.com/i.test(url)) fmt = 'slack';
      else if (/discord(app)?\.com\/api\/webhooks/i.test(url)) fmt = 'discord';
      else fmt = 'generic';
    }
    if (fmt === 'feishu') payload = { msg_type: 'text', content: { text } };
    else if (fmt === 'wecom') payload = { msgtype: 'text', text: { content: text } };
    else if (fmt === 'slack' || fmt === 'discord') payload = { text };
    else payload = { source: 'agent-platform', kind, text, at: new Date().toISOString() };
  }
}
/* ---- optional push actions (buttons / hints) ----
   Callers may pass `actions: [{label, kind, id, hours}]`. Telegram gets real
   inline buttons; every other channel gets a plain-text hint. No actions ->
   byte-identical to before. */
let pushActions = [];
try {
  pushActions = (Array.isArray(body.actions) ? body.actions : [])
    .filter((a) => a && a.kind && a.id)
    .slice(0, 3);
} catch (eA) { pushActions = []; }
if (pushActions.length) {
  const cbOf = (a) => 'ap:' + String(a.kind).slice(0, 4) + ':' + String(a.id) + (a.hours ? ':' + String(a.hours) : '');
  const isTg = String(url).indexOf('api.telegram.org') !== -1;
  if (isTg) {
    payload = payload || {};
    payload.reply_markup = {
      inline_keyboard: [pushActions.map((a) => ({ text: String(a.label || a.kind), callback_data: cbOf(a) }))],
    };
  } else {
    const hint = String.fromCharCode(10) + '可操作：' + pushActions.map((a) => String(a.label || a.kind)).join(' / ');
    text = (text + hint).slice(0, 4000);
    payload = payload || {};
    if (typeof payload.text === 'string') payload.text = text;
    else if (payload.content && typeof payload.content.text === 'string') payload.content.text = text;
  }
}
return [{ json: { ok: true, kind, fmt, url, payload, owner, degraded, resolved_to, via } }];

/* Normalise the delivery result for the caller (B2: surface routing info). */
const d = $input.first().json || {};
let meta = {};
try { meta = $('Parse & Auth').first().json || {}; } catch (e) { meta = {}; }
const base = meta.owner ? { degraded: !!meta.degraded, owner: String(meta.owner || ''), resolved_to: String(meta.resolved_to || ''), via: String(meta.via || 'default') } : {};;
if (d.error) {
  return [{ json: Object.assign({}, base, { ok: false, reason: 'delivery_failed', detail: String((d.error && d.error.message) || d.error).slice(0, 180) }) }];
}
if (typeof d.code === 'number' && d.code !== 0) {
  return [{ json: Object.assign({}, base, { ok: false, reason: 'delivery_rejected', detail: JSON.stringify(d).slice(0, 180) }) }];
}
return [{ json: Object.assign({}, base, { ok: true, delivered: true }) }];
